\begin{aligned}
\mathrm{IsImageMono}_{\mathcal E}(f,m)\Longleftrightarrow{}&\mathrm{IsMono}(m)\land\mathrm{cod}(m)=\mathrm{cod}(f)\\
&\land\exists e_0\in\mathrm{Hom}(\mathrm{dom}(f),\mathrm{dom}(m))\ (m\circ e_0=f)\\
&\land\forall J\in\mathrm{Ob}(\mathcal E)\ \forall h\in\mathrm{Hom}(J,\mathrm{cod}(f))\ \forall g\in\mathrm{Hom}(\mathrm{dom}(f),J)\\
&\quad(\mathrm{IsMono}(h)\land h\circ g=f\Rightarrow\exists v_0\in\mathrm{Hom}(\mathrm{dom}(m),J)\ (h\circ v_0=m)).
\end{aligned}
